@startuml

class Line {
  + name : string
}

class Piece {
  + type : string
  + reference : string
  + sellingPrice : double
}

class Component {
  + manufacturingPrice : double
}

class ComponentType {
  + code : int
  + type : string
}

class Store {
  + address : string
  + faxNumber : string
}

class Order {
  + orderNumber : string
  + date : date
}

class PieceComponent {
  + quantity : int
}

class PieceOrder {
  + quantity : int
}

Line "1" -- "*" Piece : consists of
Piece "*" -- "1" Line
Component "*" -- "1" ComponentType
Piece "*" -- "*" Component : composed of
PieceComponent "*" -- "1" Piece
PieceComponent "*" -- "1" Component
Store "1" -- "*" Order : places
Order "*" -- "1" Store
Order "*" -- "*" Piece : contains
PieceOrder "*" -- "1" Order
PieceOrder "*" -- "1" Piece

@enduml

